namespace {

constexpr SINT kChunkFrames = 4096;

double elapsedMilliseconds(const QElapsedTimer& timer) {
    return static_cast<double>(timer.nsecsElapsed()) / 1e6;
}

QJsonValue residentBytes(bool peak) {
#ifdef __linux__
    QFile status(QStringLiteral("/proc/self/status"));
    if (status.open(QIODevice::ReadOnly)) {
        const auto pattern = peak ? QStringLiteral("(?:^|\\n)VmHWM:\\s+(\\d+) kB")
                                  : QStringLiteral("(?:^|\\n)VmRSS:\\s+(\\d+) kB");
        const auto match = QRegularExpression(pattern).match(QString::fromUtf8(status.readAll()));
        if (match.hasMatch())
            return match.captured(1).toDouble() * 1024;
    }
#else
    static_cast<void>(peak);
#endif
    return QJsonValue::Null;
}

QJsonValue inheritedMaxRssDiagnostic() {
#ifdef __linux__
    rusage usage{};
    if (getrusage(RUSAGE_SELF, &usage) == 0) {
        return static_cast<double>(usage.ru_maxrss) * 1024;
    }
#endif
    return QJsonValue::Null;
}

QString fileSha256(const QString& path) {
    QFile input(path);
    if (!input.open(QIODevice::ReadOnly))
        throw std::runtime_error("cannot read input file");
    QCryptographicHash hash(QCryptographicHash::Sha256);
    while (!input.atEnd()) {
        const auto block = input.read(1024 * 1024);
        if (block.isEmpty() && input.error() != QFileDevice::NoError) {
            throw std::runtime_error("input file hashing failed");
        }
        hash.addData(block);
    }
    return QString::fromLatin1(hash.result().toHex());
}

mixxx::BeatGridMode parseMode(const QString& mode) {
    if (mode == QStringLiteral("constant"))
        return mixxx::BeatGridMode::Constant;
    if (mode == QStringLiteral("variable"))
        return mixxx::BeatGridMode::Variable;
    if (mode == QStringLiteral("auto"))
        return mixxx::BeatGridMode::Auto;
    throw std::runtime_error("unsupported comparison tempo mode");
}

} // namespace

class PhaseGridFileComparisonTest : public MixxxTest, private SoundSourceProviderRegistration {};

TEST_F(PhaseGridFileComparisonTest, ExportConfiguredPcm) {
    const auto input = qEnvironmentVariable("MIXXX_PHASEGRID_INPUT");
    const auto output = qEnvironmentVariable("MIXXX_PHASEGRID_OUTPUT");
    const auto pcmPath = qEnvironmentVariable("MIXXX_PHASEGRID_PCM");
    if (input.isEmpty() || output.isEmpty() || pcmPath.isEmpty()) {
        GTEST_SKIP() << "Set input, output and PCM paths for offline diagnostic export";
    }
    ASSERT_NE(QFileInfo(input).absoluteFilePath(), QFileInfo(pcmPath).absoluteFilePath());
    ASSERT_NE(QFileInfo(input).absoluteFilePath(), QFileInfo(output).absoluteFilePath());
    auto track = Track::newTemporary(input);
    SoundSourceProxy proxy(track);
    mixxx::AudioSource::OpenParams open;
    open.setChannelCount(mixxx::audio::ChannelCount::stereo());
    auto audio = proxy.openAudioSource(open);
    ASSERT_TRUE(audio);
    if (audio->getSignalInfo().getChannelCount() != mixxx::audio::ChannelCount::stereo()) {
        audio = mixxx::AudioSourceStereoProxy::create(audio, kChunkFrames);
    }
    ASSERT_TRUE(audio);
    ASSERT_EQ(mixxx::audio::ChannelCount::stereo(), audio->getSignalInfo().getChannelCount());
    const auto rate = audio->getSignalInfo().getSampleRate();
    ASSERT_TRUE(rate.isValid());
    QFile pcm(pcmPath);
    ASSERT_TRUE(pcm.open(QIODevice::WriteOnly | QIODevice::Truncate));
    QCryptographicHash hash(QCryptographicHash::Sha256);
    mixxx::SampleBuffer buffer(kChunkFrames * 2);
    SINT decoded = 0;
    for (SINT position = audio->frameIndexMin(); position < audio->frameIndexMax();) {
        const auto read = audio->readSampleFrames(mixxx::WritableSampleFrames(
                mixxx::IndexRange::forward(
                        position, std::min(kChunkFrames, audio->frameIndexMax() - position)),
                mixxx::SampleBuffer::WritableSlice(buffer)));
        const auto range = read.frameIndexRange();
        ASSERT_FALSE(range.empty());
        ASSERT_EQ(position, range.start());
        ASSERT_LE(range.end(), audio->frameIndexMax());
        const auto bytes = range.length() * 2 * static_cast<SINT>(sizeof(CSAMPLE));
        const auto* data = reinterpret_cast<const char*>(read.readableData());
        hash.addData(QByteArrayView(data, bytes));
        ASSERT_EQ(bytes, pcm.write(data, bytes));
        decoded += range.length();
        position = range.end();
    }
    pcm.close();
    QJsonObject report{{"name", QFileInfo(input).completeBaseName()},
            {"pcm_path", QFileInfo(pcmPath).absoluteFilePath()},
            {"sample_rate", static_cast<double>(rate.value())},
            {"channels", 2},
            {"decoded_frames", static_cast<double>(decoded)},
            {"duration", static_cast<double>(decoded) / rate.value()},
            {"source_sha256", fileSha256(input)},
            {"pcm_sha256", QString::fromLatin1(hash.result().toHex())},
            {"pcm_format", "native-endian float32 interleaved stereo"}};
    QFile metadata(output);
    ASSERT_TRUE(metadata.open(QIODevice::WriteOnly | QIODevice::Truncate));
    const auto json = QJsonDocument(report).toJson(QJsonDocument::Indented);
    ASSERT_EQ(json.size(), metadata.write(json));
}

TEST_F(PhaseGridFileComparisonTest, AnalyzeConfiguredFile) {
    const auto input = qEnvironmentVariable("MIXXX_PHASEGRID_INPUT");
    const auto output = qEnvironmentVariable("MIXXX_PHASEGRID_OUTPUT");
    if (input.isEmpty() || output.isEmpty()) {
        GTEST_SKIP() << "Set MIXXX_PHASEGRID_INPUT and MIXXX_PHASEGRID_OUTPUT for file comparison";
    }
    const auto backend = qEnvironmentVariable("MIXXX_PHASEGRID_BACKEND", "qm-tempotracker:0");
    const auto mode = qEnvironmentVariable("MIXXX_PHASEGRID_MODE", "constant");
    QElapsedTimer wall;
    wall.start();
    QJsonObject report{{"schema_version", 1},
            {"input_path", input},
            {"backend", backend},
            {"mode", mode},
            {"status", "error"},
            {"memory_scope",
                    "Linux VmHWM since exec through result construction: Qt, providers, decoder "
                    "and analyzer; excludes final JSON serialization/I/O"},
            {"timing_scope", "analysis excludes decoding, source/PCM hashing and result export"},
            {"pcm_format", "native-endian float32, interleaved stereo, native sample rate"},
            {"rss_before_decode_bytes", residentBytes(false)}};
    QString failure;
    try {
        bool available = false;
        for (const auto& info : AnalyzerBeats::availablePlugins())
            available |= info.id() == backend;
        if (!available)
            throw std::runtime_error("requested analyzer backend is unavailable");
        report.insert("source_size_bytes", static_cast<double>(QFileInfo(input).size()));
        report.insert("source_sha256", fileSha256(input));

        auto track = Track::newTemporary(input);
        QElapsedTimer operation;
        operation.start();
        SoundSourceProxy proxy(track);
        mixxx::AudioSource::OpenParams open;
        open.setChannelCount(mixxx::audio::ChannelCount::stereo());
        auto audio = proxy.openAudioSource(open);
        if (!audio)
            throw std::runtime_error("SoundSourceProxy could not decode input");
        if (audio->getSignalInfo().getChannelCount() != mixxx::audio::ChannelCount::stereo()) {
            audio = mixxx::AudioSourceStereoProxy::create(audio, kChunkFrames);
        }
        if (!audio ||
                audio->getSignalInfo().getChannelCount() != mixxx::audio::ChannelCount::stereo()) {
            throw std::runtime_error("decoder did not provide stereo PCM");
        }
        double decodeMs = elapsedMilliseconds(operation);
        const auto rate = audio->getSignalInfo().getSampleRate();
        const auto frameCount = audio->frameIndexMax() - audio->frameIndexMin();
        if (!rate.isValid() || frameCount <= 0)
            throw std::runtime_error("invalid decoded audio range");
        const double duration = static_cast<double>(frameCount) / rate.value();
        report.insert("sample_rate", static_cast<double>(rate.value()));
        report.insert("channels", 2);
        report.insert("declared_frames", static_cast<double>(frameCount));
        report.insert("decoder", proxy.getProvider()->getDisplayName());
        track->setBpmLocked(false);
        track->trySetBeats(mixxx::BeatsPointer());
        track->setAudioProperties(mixxx::audio::ChannelCount::stereo(),
                rate,
                mixxx::audio::Bitrate(),
                mixxx::Duration::fromSeconds(duration));
        BeatDetectionSettings settings(config());
        settings.setBeatPluginId(backend);
        settings.setTempoMode(parseMode(mode));
        settings.setBpmDetectionEnabled(true);
        settings.setFastAnalysis(false);
        settings.setReanalyzeWhenSettingsChange(true);
        AnalyzerBeats analyzer(config(), true);
        operation.restart();
        const bool initialized = analyzer.initialize(
                AnalyzerTrack(track), rate, mixxx::audio::ChannelCount::stereo(), frameCount);
        const double initializeMs = elapsedMilliseconds(operation);
        double processMs = 0;
        SINT decoded = 0;
        QCryptographicHash pcmHash(QCryptographicHash::Sha256);
        mixxx::SampleBuffer buffer(kChunkFrames * 2);
        for (SINT position = audio->frameIndexMin(); position < audio->frameIndexMax();) {
            operation.restart();
            const auto read = audio->readSampleFrames(mixxx::WritableSampleFrames(
                    mixxx::IndexRange::forward(
                            position, std::min(kChunkFrames, audio->frameIndexMax() - position)),
                    mixxx::SampleBuffer::WritableSlice(buffer)));
            decodeMs += elapsedMilliseconds(operation);
            const auto range = read.frameIndexRange();
            if (range.empty() || range.start() != position ||
                    range.end() > audio->frameIndexMax()) {
                throw std::runtime_error("decoder returned an empty or discontinuous PCM range");
            }
            const SINT samples = range.length() * 2;
            pcmHash.addData(QByteArrayView(reinterpret_cast<const char*>(read.readableData()),
                    samples * static_cast<SINT>(sizeof(CSAMPLE))));
            if (initialized) {
                operation.restart();
                const bool accepted = analyzer.processSamples(read.readableData(), samples);
                processMs += elapsedMilliseconds(operation);
                if (!accepted)
                    throw std::runtime_error("analyzer rejected a decoded PCM block");
            }
            decoded += range.length();
            position = range.end();
        }
        operation.restart();
        if (initialized)
            analyzer.storeResults(track);
        const double finalizeMs = elapsedMilliseconds(operation);
        operation.restart();
        analyzer.cleanup();
        report.insert("cleanup_ms", elapsedMilliseconds(operation));
        report.insert("initialized", initialized);
        report.insert("decoded_frames", static_cast<double>(decoded));
        report.insert("duration_seconds", static_cast<double>(decoded) / rate.value());
        report.insert("pcm_sha256", QString::fromLatin1(pcmHash.result().toHex()));
        report.insert("decode_ms", decodeMs);
        report.insert("initialize_ms", initializeMs);
        report.insert("process_ms", processMs);
        report.insert("finalize_ms", finalizeMs);
        report.insert("analysis_ms", initializeMs + processMs + finalizeMs);
        const auto beats = track->getBeats();
        if (!beats) {
            report.insert("status", "noresult");
            report.insert(
                    "reason", initialized ? "no beat grid produced" : "initialization declined");
        } else {
            const auto bpm = beats->getBpmInRange(
                    mixxx::audio::kStartFramePos, mixxx::audio::FramePos(decoded));
            if (!bpm.isValid() || !util_isfinite(static_cast<double>(bpm.value()))) {
                throw std::runtime_error("analyzer produced an invalid BPM");
            }
            report.insert("status", "success");
            report.insert("bpm", bpm.value());
            report.insert("constant", beats->hasConstantTempo());
            report.insert("first_beat_seconds", beats->firstBeat().value() / rate.value());
            QJsonArray times;
            double previous = -1;
            for (auto beat = beats->iteratorFrom(mixxx::audio::kStartFramePos);
                    (*beat).value() < decoded;
                    ++beat) {
                const double time = (*beat).value() / rate.value();
                if (!util_isfinite(time) || time <= previous || times.size() >= 10000000) {
                    throw std::runtime_error("invalid or unbounded beat export");
                }
                previous = time;
                if (time >= 0)
                    times.append(time);
            }
            report.insert("beat_times_seconds", times);
            QJsonArray local;
            constexpr double window = 8;
            constexpr double stride = 4;
            for (double start = 0; start < duration; start += stride) {
                const double end = std::min(duration, start + window);
                const auto localBpm =
                        beats->getBpmInRange(mixxx::audio::FramePos(start * rate.value()),
                                mixxx::audio::FramePos(end * rate.value()));
                local.append(QJsonObject{{"start_seconds", start},
                        {"end_seconds", end},
                        {"bpm",
                                localBpm.isValid() &&
                                                util_isfinite(static_cast<double>(localBpm.value()))
                                        ? QJsonValue(localBpm.value())
                                        : QJsonValue::Null}});
                if (end == duration)
                    break;
            }
            report.insert("local_bpm_windows", local);
            report.insert("beat_subversion", beats->getSubVersion());
        }
    } catch (const std::exception& error) {
        failure = QString::fromUtf8(error.what());
        report.insert("error", failure);
        report.insert("status", "error");
    }
    report.insert("rss_after_analysis_bytes", residentBytes(false));
    report.insert("peak_rss_bytes", residentBytes(true));
    report.insert("peak_rss_method",
            "VmHWM since exec, sampled before final JSON serialization and output I/O");
    report.insert("getrusage_maxrss_diagnostic_bytes", inheritedMaxRssDiagnostic());
    report.insert("getrusage_maxrss_scope",
            "may retain launcher high-water mark; not used for comparisons");
    report.insert("total_wall_ms", elapsedMilliseconds(wall));
    QFile result(output);
    ASSERT_TRUE(result.open(QIODevice::WriteOnly | QIODevice::Truncate)) << qPrintable(output);
    const auto json = QJsonDocument(report).toJson(QJsonDocument::Indented);
    ASSERT_EQ(json.size(), result.write(json));
    result.close();
    EXPECT_TRUE(failure.isEmpty()) << qPrintable(failure);
}
